{
  "name": "Draw 3D Layout",
  "description": "A SketchUp-lite web application for factory general affairs to quickly draw, extrude, and visualize 3D space layouts using simple drawing tools and AI assistance."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { Vector3 } from 'three';

export enum ToolType {
  SELECT = 'SELECT',
  DRAW = 'DRAW',
  EXTRUDE = 'EXTRUDE', // Simplified to height adjustment
  MEASURE = 'MEASURE',
  DELETE = 'DELETE'
}

export interface IPoint {
  x: number;
  y: number; // In 3D logic this might be Z, but for 2D shape drawing we store x,y
  z: number;
}

export interface IShape {
  id: string;
  points: IPoint[]; // 2D footprint on the ground
  height: number;
  color: string;
  position: [number, number, number];
  rotation: number; // Y-axis rotation in radians
  name: string;
}

export interface ISceneState {
  shapes: IShape[];
  selectedId: string | null;
  tool: ToolType;
  gridSize: number;
}

// AI Generation Types
export interface AIGeneratedItem {
  name: string;
  width: number;
  depth: number;
  height: number;
  color: string;
  x: number;
  z: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { AI_SYSTEM_INSTRUCTION } from '../constants';
import { AIGeneratedItem } from '../types';

let genAI: GoogleGenAI | null = null;

const getAIClient = () => {
  if (!genAI && process.env.API_KEY) {
    genAI = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }
  return genAI;
};

export const generateLayoutFromPrompt = async (userPrompt: string): Promise<AIGeneratedItem[]> => {
  const ai = getAIClient();
  if (!ai) {
    throw new Error("API Key not configured");
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userPrompt,
      config: {
        systemInstruction: AI_SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING, description: "Name of the object (e.g., Table, Rack)" },
              width: { type: Type.NUMBER, description: "Width in meters (x-axis dimension)" },
              depth: { type: Type.NUMBER, description: "Depth in meters (z-axis dimension)" },
              height: { type: Type.NUMBER, description: "Height in meters (extrusion amount)" },
              color: { type: Type.STRING, description: "Hex color code" },
              x: { type: Type.NUMBER, description: "Position X coordinate" },
              z: { type: Type.NUMBER, description: "Position Z coordinate" },
            },
            required: ["name", "width", "depth", "height", "color", "x", "z"]
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as AIGeneratedItem[];
    }
    return [];
  } catch (error) {
    console.error("Gemini generation error:", error);
    throw error;
  }
};

import React, { createContext, useContext, useState, useCallback } from 'react';
import { IShape, ToolType, IPoint } from '../types';
import { DEFAULT_HEIGHT, DEFAULT_COLOR } from '../constants';

interface AppContextType {
  shapes: IShape[];
  addShape: (shape: IShape) => void;
  updateShape: (id: string, updates: Partial<IShape>) => void;
  removeShape: (id: string) => void;
  selectedId: string | null;
  setSelectedId: (id: string | null) => void;
  tool: ToolType;
  setTool: (tool: ToolType) => void;
  clearScene: () => void;
  addAIShapes: (items: any[]) => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [shapes, setShapes] = useState<IShape[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);

  const addShape = useCallback((shape: IShape) => {
    setShapes(prev => [...prev, shape]);
  }, []);

  const updateShape = useCallback((id: string, updates: Partial<IShape>) => {
    setShapes(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
  }, []);

  const removeShape = useCallback((id: string) => {
    setShapes(prev => prev.filter(s => s.id !== id));
    if (selectedId === id) setSelectedId(null);
  }, [selectedId]);

  const clearScene = useCallback(() => {
    setShapes([]);
    setSelectedId(null);
  }, []);

  const addAIShapes = useCallback((items: any[]) => {
    const newShapes: IShape[] = items.map((item, index) => {
      // Convert Box dimensions to a 2D Polygon footprint centered at 0,0 locally
      const w = item.width / 2;
      const d = item.depth / 2;
      const points: IPoint[] = [
        { x: -w, y: 0, z: -d },
        { x: w, y: 0, z: -d },
        { x: w, y: 0, z: d },
        { x: -w, y: 0, z: d },
        { x: -w, y: 0, z: -d }, // Close loop
      ];

      return {
        id: `ai-${Date.now()}-${index}`,
        name: item.name,
        points,
        height: item.height,
        color: item.color || DEFAULT_COLOR,
        position: [item.x, 0, item.z],
        rotation: 0
      };
    });
    setShapes(prev => [...prev, ...newShapes]);
  }, []);

  return (
    <AppContext.Provider value={{
      shapes,
      addShape,
      updateShape,
      removeShape,
      selectedId,
      setSelectedId,
      tool,
      setTool,
      clearScene,
      addAIShapes
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React from 'react';
import { useApp } from '../context/AppContext';
import { ToolType } from '../types';
import { 
  MousePointer2, 
  PenTool, 
  Scaling, 
  Ruler, 
  Trash2, 
  Eraser,
  Box
} from 'lucide-react';

const Toolbar: React.FC = () => {
  const { tool, setTool, clearScene } = useApp();

  const tools = [
    { type: ToolType.SELECT, icon: <MousePointer2 size={20} />, label: "Select" },
    { type: ToolType.DRAW, icon: <PenTool size={20} />, label: "Draw" },
    // Extrude is now integrated into selection properties, but we keep a "Mode" logic if needed. 
    // For simplicity, we stick to drawing and selecting to edit.
    { type: ToolType.MEASURE, icon: <Ruler size={20} />, label: "Measure" },
  ];

  return (
    <div className="absolute top-4 left-4 flex flex-col gap-2 bg-slate-800/90 p-2 rounded-xl border border-slate-700 shadow-xl backdrop-blur-sm z-10">
      <div className="text-xs text-slate-400 font-bold px-2 py-1 text-center border-b border-slate-700 mb-1">
        TOOLS
      </div>

      {tools.map((t) => (
        <button
          key={t.type}
          onClick={() => setTool(t.type)}
          className={`flex items-center gap-2 p-3 rounded-lg transition-all duration-200 group relative
            ${tool === t.type 
              ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' 
              : 'text-slate-400 hover:bg-slate-700 hover:text-white'
            }`}
          title={t.label}
        >
          {t.icon}
          {/* Tooltip */}
          <span className="absolute left-full ml-3 px-2 py-1 bg-black text-white text-xs rounded opacity-0 group-hover:opacity-100 whitespace-nowrap pointer-events-none transition-opacity">
            {t.label}
          </span>
        </button>
      ))}

      <div className="h-px bg-slate-700 my-1 mx-2" />

      <button
        onClick={clearScene}
        className="flex items-center gap-2 p-3 rounded-lg text-red-400 hover:bg-red-500/10 hover:text-red-300 transition-all duration-200 group relative"
        title="Clear All"
      >
        <Eraser size={20} />
      </button>
    </div>
  );
};

export default Toolbar;

import React from 'react';
import { useApp } from '../context/AppContext';
import { PRESET_COLORS, DEFAULT_HEIGHT } from '../constants';
import { Trash2, BoxSelect } from 'lucide-react';

const PropertiesPanel: React.FC = () => {
