      <div className="absolute top-4 right-4 w-64 p-4 bg-slate-800/90 backdrop-blur-sm rounded-xl border border-slate-700 shadow-xl z-10 text-slate-400 text-sm flex flex-col items-center justify-center min-h-[100px]">
        <BoxSelect className="mb-2 opacity-50" size={32} />
        <p>Select an object to edit</p>
      </div>
    );
  }

  const selectedShape = shapes.find(s => s.id === selectedId);
  if (!selectedShape) return null;

  return (
    <div className="absolute top-4 right-4 w-72 bg-slate-800/90 backdrop-blur-sm rounded-xl border border-slate-700 shadow-xl z-10 flex flex-col overflow-hidden">
      <div className="p-4 border-b border-slate-700 bg-slate-900/50 flex justify-between items-center">
        <h3 className="text-white font-semibold flex items-center gap-2">
          <span className="w-2 h-6 bg-blue-500 rounded-full"/>
          Properties
        </h3>
        <button 
          onClick={() => removeShape(selectedId)}
          className="text-red-400 hover:text-red-300 p-1 hover:bg-red-500/10 rounded transition-colors"
          title="Delete Object"
        >
          <Trash2 size={18} />
        </button>
      </div>

      <div className="p-4 space-y-6">

        {/* Name */}
        <div className="space-y-2">
            <label className="text-xs text-slate-400 font-medium uppercase tracking-wider">Name</label>
            <input 
                type="text" 
                value={selectedShape.name} 
                onChange={(e) => updateShape(selectedId, { name: e.target.value })}
                className="w-full bg-slate-900 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:border-blue-500 focus:outline-none"
            />
        </div>

        {/* Height Slider (Push/Pull simplified) */}
        <div className="space-y-3">
          <div className="flex justify-between items-center">
             <label className="text-xs text-slate-400 font-medium uppercase tracking-wider">Height (Extrude)</label>
             <span className="text-blue-400 font-mono text-sm">{selectedShape.height.toFixed(2)}m</span>
          </div>
          <input
            type="range"
            min="0.1"
            max="10"
            step="0.1"
            value={selectedShape.height}
            onChange={(e) => updateShape(selectedId, { height: parseFloat(e.target.value) })}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
          />
        </div>

        {/* Rotation */}
        <div className="space-y-3">
          <div className="flex justify-between items-center">
             <label className="text-xs text-slate-400 font-medium uppercase tracking-wider">Rotation</label>
             <span className="text-blue-400 font-mono text-sm">{((selectedShape.rotation * 180) / Math.PI).toFixed(0)}°</span>
          </div>
          <input
            type="range"
            min="0"
            max={Math.PI * 2}
            step="0.1"
            value={selectedShape.rotation}
            onChange={(e) => updateShape(selectedId, { rotation: parseFloat(e.target.value) })}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
          />
        </div>

        {/* Color Picker */}
        <div className="space-y-2">
          <label className="text-xs text-slate-400 font-medium uppercase tracking-wider">Material Color</label>
          <div className="grid grid-cols-4 gap-2">
            {PRESET_COLORS.map(color => (
              <button
                key={color}
                onClick={() => updateShape(selectedId, { color })}
                className={`w-full aspect-square rounded-md border-2 transition-transform hover:scale-105 ${selectedShape.color === color ? 'border-white ring-2 ring-blue-500/50' : 'border-transparent'}`}
                style={{ backgroundColor: color }}
              />
            ))}
            <div className="relative w-full aspect-square rounded-md overflow-hidden bg-gradient-to-br from-white to-black border-2 border-slate-600">
                <input 
                    type="color" 
                    className="absolute inset-0 w-[150%] h-[150%] -top-1/4 -left-1/4 cursor-pointer opacity-0" 
                    value={selectedShape.color}
                    onChange={(e) => updateShape(selectedId, { color: e.target.value })}
                />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PropertiesPanel;

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { generateLayoutFromPrompt } from '../services/geminiService';
import { Sparkles, Loader2, AlertCircle } from 'lucide-react';

const AIAssistant: React.FC = () => {
  const { addAIShapes } = useApp();
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isOpen, setIsOpen] = useState(false);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;

    setLoading(true);
    setError(null);

    try {
      if (!process.env.API_KEY) {
        throw new Error("API Key is not configured in the environment.");
      }
      const items = await generateLayoutFromPrompt(prompt);
      addAIShapes(items);
      setPrompt('');
      setIsOpen(false);
    } catch (err: any) {
      setError(err.message || "Failed to generate layout.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="absolute bottom-4 left-4 z-10 flex flex-col items-start gap-2">
      {isOpen && (
        <div className="w-80 bg-slate-800/95 backdrop-blur-md rounded-xl border border-indigo-500/50 shadow-2xl p-4 animate-in fade-in slide-in-from-bottom-4">
          <div className="flex items-center gap-2 mb-3 text-indigo-400 font-semibold">
            <Sparkles size={18} />
            <h3>AI Layout Assistant</h3>
          </div>

          <p className="text-slate-300 text-sm mb-3">
            Describe a room or layout (e.g., "A meeting room with a large wooden table and 4 chairs").
          </p>

          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white text-sm focus:border-indigo-500 focus:outline-none resize-none h-24 mb-3"
            placeholder="Describe your layout..."
          />

          {error && (
            <div className="flex items-center gap-2 text-red-400 text-xs mb-3 bg-red-500/10 p-2 rounded">
              <AlertCircle size={14} />
              {error}
            </div>
          )}

          <div className="flex justify-end gap-2">
            <button 
              onClick={() => setIsOpen(false)}
              className="px-3 py-1.5 text-xs text-slate-400 hover:text-white transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={handleGenerate}
              disabled={loading || !prompt.trim()}
              className="flex items-center gap-2 px-4 py-1.5 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 text-white text-sm rounded-lg font-medium transition-colors"
            >
              {loading && <Loader2 size={14} className="animate-spin" />}
              {loading ? 'Thinking...' : 'Generate'}
            </button>
          </div>
        </div>
      )}

      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`flex items-center gap-2 px-4 py-3 rounded-full shadow-lg transition-all duration-300 font-semibold border
          ${isOpen ? 'bg-indigo-600 text-white border-indigo-500' : 'bg-slate-800 text-indigo-400 border-indigo-500/30 hover:bg-slate-700'}`}
      >
        <Sparkles size={20} className={loading ? "animate-pulse" : ""} />
        {isOpen ? 'Close Assistant' : 'AI Assistant'}
      </button>
    </div>
  );
};

export default AIAssistant;

import React, { useRef, useState, useMemo } from 'react';
import { Canvas, useThree, ThreeEvent } from '@react-three/fiber';
import { OrbitControls, Grid, Sky, Environment } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';

// Helper to convert 2D points to Three Shape
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (points.length === 0) return shape;

  shape.moveTo(points[0].x, points[0].z);
  for (let i = 1; i < points.length; i++) {
    shape.lineTo(points[i].x, points[i].z);
  }
  shape.closePath();
  return shape;
};

// Component to handle drawing logic
const DrawingPlane: React.FC = () => {
  const { tool, addShape } = useApp();
  const [drawingPoints, setDrawingPoints] = useState<IPoint[]>([]);
  const [cursorPos, setCursorPos] = useState<IPoint | null>(null);

  const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
    if (tool !== ToolType.DRAW) return;
    // Snap to grid
    const x = Math.round(e.point.x / SNAP_GRID) * SNAP_GRID;
    const z = Math.round(e.point.z / SNAP_GRID) * SNAP_GRID;
    setCursorPos({ x, y: 0, z });
  };

  const handleClick = (e: ThreeEvent<MouseEvent>) => {
    if (tool !== ToolType.DRAW) return;
    e.stopPropagation();

    const x = Math.round(e.point.x / SNAP_GRID) * SNAP_GRID;
    const z = Math.round(e.point.z / SNAP_GRID) * SNAP_GRID;
    const newPoint = { x, y: 0, z };

    // Check for close shape (clicking near start)
    if (drawingPoints.length > 2) {
      const start = drawingPoints[0];
      const dist = Math.sqrt(Math.pow(x - start.x, 2) + Math.pow(z - start.z, 2));

      if (dist < 0.5) {
        // Close shape
        finishShape();
        return;
      }
    }

    setDrawingPoints([...drawingPoints, newPoint]);
  };

  const finishShape = () => {
    if (drawingPoints.length < 3) return;

    // Add start point at end to ensure loop for logic, though Shape handles close
    const closedPoints = [...drawingPoints, drawingPoints[0]];

    const newShape: IShape = {
      id: `shape-${Date.now()}`,
      name: `Object ${Date.now().toString().slice(-4)}`,
      points: closedPoints,
      height: DEFAULT_HEIGHT,
      color: DEFAULT_COLOR,
      position: [0, 0, 0], // Drawn in world coords, so position is 0,0,0 relative
      rotation: 0,
    };

    addShape(newShape);
    setDrawingPoints([]);
    setCursorPos(null);
  };

  return (
    <>
      {/* Invisible plane for catching raycasts */}
      <mesh 
        rotation={[-Math.PI / 2, 0, 0]} 
        position={[0, -0.01, 0]} 
        onPointerMove={handlePointerMove}
        onClick={handleClick}
        visible={false}
      >
        <planeGeometry args={[100, 100]} />
      </mesh>

      {/* Visual Guide for Cursor */}
      {tool === ToolType.DRAW && cursorPos && (
        <mesh position={[cursorPos.x, 0.05, cursorPos.z]} rotation={[-Math.PI / 2, 0, 0]}>
          <ringGeometry args={[0.1, 0.15, 32]} />
          <meshBasicMaterial color="red" />
        </mesh>
      )}

      {/* Visual Guide for Line being drawn */}
      {drawingPoints.length > 0 && (
        <line>
          <bufferGeometry>
            <bufferAttribute
              attach="attributes-position"
              count={drawingPoints.length + (cursorPos ? 1 : 0)}
              array={new Float32Array([
                ...drawingPoints.flatMap(p => [p.x, 0.1, p.z]),
                ...(cursorPos ? [cursorPos.x, 0.1, cursorPos.z] : [])
              ])}
              itemSize={3}
            />
          </bufferGeometry>
          <lineBasicMaterial color="red" linewidth={2} />
        </line>
      )}
    </>
  );
};

// Individual Extruded Shape
const RenderedShape: React.FC<{ shape: IShape }> = ({ shape }) => {
  const { selectedId, setSelectedId, tool } = useApp();
  const isSelected = selectedId === shape.id;

  const threeShape = useMemo(() => createThreeShape(shape.points), [shape.points]);

  const extrudeSettings = useMemo(() => ({
    depth: shape.height,
    bevelEnabled: false,
  }), [shape.height]);

  const handleClick = (e: ThreeEvent<MouseEvent>) => {
    if (tool === ToolType.SELECT || tool === ToolType.DELETE || tool === ToolType.EXTRUDE) {
      e.stopPropagation();
      setSelectedId(shape.id);
    }
  };

  return (
    <group position={shape.position} rotation={[0, shape.rotation, 0]}>
      <mesh 
        rotation={[-Math.PI / 2, 0, 0]} 
        onClick={handleClick}
        position={[0, 0, 0]} // Pivot point logic would go here
      >
        <extrudeGeometry args={[threeShape, extrudeSettings]} />
        <meshStandardMaterial 
          color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
          transparent={isSelected} 
          opacity={isSelected ? 0.8 : 1}
        />
        {isSelected && (
           <lineSegments>
             <edgesGeometry args={[new THREE.ExtrudeGeometry(threeShape, extrudeSettings)]} />
             <lineBasicMaterial color="white" />
           </lineSegments>
        )}
      </mesh>
    </group>
  );
};

const SceneContent: React.FC = () => {
  const { shapes, tool } = useApp();

  return (
    <>
      <ambientLight intensity={0.7} />
      <directionalLight position={[10, 20, 10]} intensity={1} castShadow />
      <Environment preset="city" />

      <Grid 
        infiniteGrid 
        cellSize={1} 
        sectionSize={5} 
        fadeDistance={50} 
        sectionColor="#64748b" 
        cellColor="#475569" 
      />

      <DrawingPlane />

      {shapes.map(shape => (
        <RenderedShape key={shape.id} shape={shape} />
      ))}

      <OrbitControls 
        makeDefault 
        enabled={tool !== ToolType.DRAW} // Disable orbit when drawing to avoid confusion
        maxPolarAngle={Math.PI / 2 - 0.1} // Prevent going under the floor
      />
    </>
  );
};

const Viewport: React.FC = () => {
  return (
    <div className="w-full h-full relative bg-gradient-to-b from-slate-800 to-slate-900">
      <Canvas shadows camera={{ position: [8, 8, 8], fov: 45 }}>
        <SceneContent />
      </Canvas>

      {/* Overlay info */}
      <div className="absolute top-4 left-1/2 -translate-x-1/2 text-slate-500 text-xs pointer-events-none">
        Draw Mode: Click to add points, click start point to close loop.
      </div>
    </div>
  );
};

export default Viewport;

import React from 'react';
