  "name": "畫畫 3D 立體圖",
  "description": "一款類似 SketchUp 的 Web 應用程式，供工廠總務使用，可透過簡單的繪圖工具和 AI 輔助快速繪製、拉伸並視覺化 3D 空間佈局。",
  "requestFramePermissions": []
}

import React from 'react';
import { useApp } from '../context/AppContext';
import { ToolType } from '../types';
import { 
  MousePointer2, 
  PenTool, 
  Scaling, 
  Ruler, 
  Trash2, 
  Eraser,
  Box
} from 'lucide-react';

const Toolbar: React.FC = () => {
