import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { generateLayoutFromPrompt } from '../services/geminiService';
import { Sparkles, Loader2, AlertCircle } from 'lucide-react';

const AIAssistant: React.FC = () => {
  const { addAIShapes } = useApp();
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isOpen, setIsOpen] = useState(false);

  const handleGenerate = async () => {
    if (!prompt.trim()) return;

    setLoading(true);
    setError(null);

    try {
      if (!process.env.API_KEY) {
        throw new Error("環境中未設定 API Key。");
      }
      const items = await generateLayoutFromPrompt(prompt);
      addAIShapes(items);
      setPrompt('');
      setIsOpen(false);
    } catch (err: any) {
      setError(err.message || "生成佈局失敗。");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="absolute bottom-4 left-4 z-10 flex flex-col items-start gap-2">
      {isOpen && (
        <div className="w-80 bg-slate-800/95 backdrop-blur-md rounded-xl border border-indigo-500/50 shadow-2xl p-4 animate-in fade-in slide-in-from-bottom-4">
          <div className="flex items-center gap-2 mb-3 text-indigo-400 font-semibold">
            <Sparkles size={18} />
            <h3>AI 佈局助手</h3>
          </div>

          <p className="text-slate-300 text-sm mb-3">
            描述房間或佈局 (例如：「一間會議室，有一張大木桌和 4 把椅子」)。
          </p>

          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            className="w-full bg-slate-900 border border-slate-700 rounded-lg p-3 text-white text-sm focus:border-indigo-500 focus:outline-none resize-none h-24 mb-3"
            placeholder="描述您的佈局..."
          />

          {error && (
            <div className="flex items-center gap-2 text-red-400 text-xs mb-3 bg-red-500/10 p-2 rounded">
              <AlertCircle size={14} />
              {error}
            </div>
          )}

