import { GoogleGenAI, Type } from "@google/genai";
import { AI_SYSTEM_INSTRUCTION } from '../constants';
import { AIGeneratedItem } from '../types';

let genAI: GoogleGenAI | null = null;

const getAIClient = () => {
  if (!genAI && process.env.API_KEY) {
    genAI = new GoogleGenAI({ apiKey: process.env.API_KEY });
  }
  return genAI;
};

export const generateLayoutFromPrompt = async (userPrompt: string): Promise<AIGeneratedItem[]> => {
  const ai = getAIClient();
  if (!ai) {
    throw new Error("未設定 API Key");
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userPrompt,
      config: {
        systemInstruction: AI_SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING, description: "Name of the object (e.g., Table, Rack)" },
              width: { type: Type.NUMBER, description: "Width in meters (x-axis dimension)" },
              depth: { type: Type.NUMBER, description: "Depth in meters (z-axis dimension)" },
              height: { type: Type.NUMBER, description: "Height in meters (extrusion amount)" },
              color: { type: Type.STRING, description: "Hex color code" },
              x: { type: Type.NUMBER, description: "Position X coordinate" },
              z: { type: Type.NUMBER, description: "Position Z coordinate" },
            },
            required: ["name", "width", "depth", "height", "color", "x", "z"]
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as AIGeneratedItem[];
    }
    return [];
  } catch (error) {
    console.error("Gemini generation error:", error);
    throw error;
  }
};

import { Vector3 } from 'three';

export enum ToolType {
  SELECT = 'SELECT',
  DRAW_POLY = 'DRAW_POLY', // 原本的繪圖 (多邊形)
  DRAW_LINE = 'DRAW_LINE', // 直線 (牆)
  DRAW_RECT = 'DRAW_RECT', // 矩形
  DRAW_CIRCLE = 'DRAW_CIRCLE', // 圓形
  DRAW_ARC = 'DRAW_ARC', // 弧形 (門)
  MEASURE = 'MEASURE',
}

export type ShapeType = 'solid' | 'flat'; // 立體或平面(如門開關線)

export interface IPoint {
  x: number;
  y: number;
  z: number;
}

export interface IShape {
  id: string;
  type: ShapeType;
  points: IPoint[]; // 地面上的 2D 輪廓點
  height: number;
  color: string;
  position: [number, number, number];
  rotation: number; // Y 軸旋轉 (弧度)
  name: string;
}

export interface ISceneState {
  shapes: IShape[];
  selectedId: string | null;
  tool: ToolType;
  gridSize: number;
}

// AI Generation Types
export interface AIGeneratedItem {
  name: string;
  width: number;
  depth: number;
  height: number;
  color: string;
  x: number;
  z: number;
}

import React, { createContext, useContext, useState, useCallback } from 'react';
import { IShape, ToolType, IPoint } from '../types';
import { DEFAULT_HEIGHT, DEFAULT_COLOR } from '../constants';

type UnitType = 'm' | 'cm';

interface AppContextType {
  shapes: IShape[];
  addShape: (shape: IShape) => void;
  updateShape: (id: string, updates: Partial<IShape>) => void;
  removeShape: (id: string) => void;
  copyShape: (id: string) => void;
  selectedId: string | null;
  setSelectedId: (id: string | null) => void;
  tool: ToolType;
  setTool: (tool: ToolType) => void;
  clearScene: () => void;
  addAIShapes: (items: any[]) => void;
  unit: UnitType;
  setUnit: (unit: UnitType) => void;
  formatValue: (val: number) => string;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [shapes, setShapes] = useState<IShape[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [unit, setUnit] = useState<UnitType>('m');

  const addShape = useCallback((shape: IShape) => {
    setShapes(prev => [...prev, shape]);
    // 自動選取剛畫完的物件
    if (shape.id) setSelectedId(shape.id);
    // 畫完後切換回選取模式 (可選，這裡保留畫圖模式以便連續畫，或者切回Select)
    // 這裡設為切回 Select 以避免誤觸，但如果是連續畫圖軟體通常會保持。
    // 為了使用者體驗：如果是多邊形(DRAW_POLY)通常保持，若是矩形/圓形通常也保持。
    // 這裡暫時保持工具狀態。
  }, []);

  const updateShape = useCallback((id: string, updates: Partial<IShape>) => {
    setShapes(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
  }, []);

  const removeShape = useCallback((id: string) => {
    setShapes(prev => prev.filter(s => s.id !== id));
    if (selectedId === id) setSelectedId(null);
  }, [selectedId]);

  const copyShape = useCallback((id: string) => {
    setShapes(prev => {
      const target = prev.find(s => s.id === id);
      if (!target) return prev;

      const newShape: IShape = {
        ...target,
        id: `copy-${Date.now()}`,
        name: `${target.name} (複製)`,
        position: [target.position[0] + 1, target.position[1], target.position[2] + 1] // 稍微錯位
      };
      return [...prev, newShape];
    });
  }, []);

  const clearScene = useCallback(() => {
    setShapes([]);
    setSelectedId(null);
  }, []);

  const addAIShapes = useCallback((items: any[]) => {
    const newShapes: IShape[] = items.map((item, index) => {
      const w = item.width / 2;
      const d = item.depth / 2;
      const points: IPoint[] = [
        { x: -w, y: 0, z: -d },
        { x: w, y: 0, z: -d },
        { x: w, y: 0, z: d },
        { x: -w, y: 0, z: d },
        { x: -w, y: 0, z: -d },
      ];

      return {
        id: `ai-${Date.now()}-${index}`,
        type: 'solid',
        name: item.name,
        points,
        height: item.height,
        color: item.color || DEFAULT_COLOR,
        position: [item.x, 0, item.z],
        rotation: 0
      };
    });
    setShapes(prev => [...prev, ...newShapes]);
  }, []);

  const formatValue = useCallback((val: number) => {
    if (unit === 'cm') {
      return `${(val * 100).toFixed(0)} cm`;
    }
    return `${val.toFixed(2)} m`;
  }, [unit]);

  return (
    <AppContext.Provider value={{
      shapes,
      addShape,
      updateShape,
      removeShape,
      copyShape,
      selectedId,
      setSelectedId,
      tool,
      setTool,
      clearScene,
      addAIShapes,
      unit,
      setUnit,
      formatValue
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

