import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Canvas, useThree, ThreeEvent } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';

// Helper: Convert 2D points to Three Shape
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (points.length === 0) return shape;

  shape.moveTo(points[0].x, points[0].z);
  for (let i = 1; i < points.length; i++) {
    shape.lineTo(points[i].x, points[i].z);
  }
  shape.closePath();
  return shape;
};

// Helper: Generate points for a circle
const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  // Close loop
  points.push(points[0]);
  return points;
};

// Helper: Generate points for a quarter arc (door swing)
const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  // Center point
  points.push({ x: 0, y: 0, z: 0 });
  // Arc points (0 to 90 degrees)
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); // 90 degrees
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  // Close shape back to center
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

// Component: Cursor Tooltip for dimensions
const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3 }> = ({ text, position }) => {
  return (
    <Html position={[position.x, 0.5, position.z]} center style={{ pointerEvents: 'none' }}>
      <div className="bg-black/80 text-white text-xs px-2 py-1 rounded whitespace-nowrap backdrop-blur-sm border border-white/20">
        {text}
      </div>
    </Html>
  );
};

// Component: Handles Drawing Logic for all tools
const DrawingManager: React.FC = () => {
  const { tool, addShape, formatValue } = useApp();
  const [startPoint, setStartPoint] = useState<IPoint | null>(null);
  const [currentPoint, setCurrentPoint] = useState<IPoint | null>(null);
  const [polyPoints, setPolyPoints] = useState<IPoint[]>([]);

  // Reset when tool changes
  useEffect(() => {
    setStartPoint(null);
    setCurrentPoint(null);
    setPolyPoints([]);
  }, [tool]);

  const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
    if (tool === ToolType.SELECT || tool === ToolType.MEASURE) return;
    const x = Math.round(e.point.x / SNAP_GRID) * SNAP_GRID;
    const z = Math.round(e.point.z / SNAP_GRID) * SNAP_GRID;
    setCurrentPoint({ x, y: 0, z });
  };

  const handleClick = (e: ThreeEvent<MouseEvent>) => {
    if (tool === ToolType.SELECT || tool === ToolType.MEASURE) return;
    e.stopPropagation();

    const x = Math.round(e.point.x / SNAP_GRID) * SNAP_GRID;
    const z = Math.round(e.point.z / SNAP_GRID) * SNAP_GRID;
    const p = { x, y: 0, z };

    if (tool === ToolType.DRAW_POLY) {
      // Polygon Logic
      if (polyPoints.length > 2) {
         const start = polyPoints[0];
         const dist = Math.sqrt(Math.pow(x - start.x, 2) + Math.pow(z - start.z, 2));
         if (dist < 0.5) {
           finishShape(polyPoints); // Close loop
           return;
         }
      }
      setPolyPoints([...polyPoints, p]);
    } else {
      // 2-Step Tools (Line, Rect, Circle, Arc)
      if (!startPoint) {
        setStartPoint(p);
      } else {
        finishPrimitive(startPoint, p);
      }
    }
  };

  const finishPrimitive = (start: IPoint, end: IPoint) => {
    let points: IPoint[] = [];
    let shapeType: ShapeType = 'solid';
    let name = "Object";
    let pos: [number, number, number] = [0,0,0];

    const dx = end.x - start.x;
    const dz = end.z - start.z;
    const dist = Math.sqrt(dx*dx + dz*dz);

    if (dist < 0.1) return; // Too small

    switch (tool) {
      case ToolType.DRAW_LINE:
        // Create a wall (Line with thickness)
        const thickness = 0.2; // 20cm wall
        const angle = Math.atan2(dz, dx);
        const perpX = Math.sin(angle) * (thickness/2);
        const perpZ = -Math.cos(angle) * (thickness/2);

        // Define points relative to center? No, let's define absolute then shift to relative.
        // Actually, let's create points centered at 0,0 and move the object to midpoint.
        const len = dist;
        points = [
          { x: 0, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: -thickness/2 }
        ];
        pos = [start.x, 0, start.z]; // Pivot at start
        // Rotation will be handled by the object property? 
        // For line, we want to rotate it to match the drawn angle.
        // But IShape rotation rotates the whole object.
        // So we set points as a rectangle of length `dist` along X axis, then rotate object.
        // Pivot is start point.
        name = "牆面";
        break;

      case ToolType.DRAW_RECT:
        // Rectangle defined by diagonal
        const w = Math.abs(dx);
        const d = Math.abs(dz);
        // Center position
        const cx = start.x + dx/2;
        const cz = start.z + dz/2;
        pos = [cx, 0, cz];
        points = [
          { x: -w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: -d/2 },
          { x: w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: d/2 },
          { x: -w/2, y: 0, z: -d/2 }
        ];
        name = "房間/區域";
        break;

      case ToolType.DRAW_CIRCLE:
        // Start is center, End is radius
        pos = [start.x, 0, start.z];
        points = createCirclePoints(dist);
        name = "圓形區域";
        break;

      case ToolType.DRAW_ARC:
        // Start is hinge, End determines radius and direction
        // Default to 90 degree arc
        pos = [start.x, 0, start.z];
        points = createArcPoints(dist);
        shapeType = 'flat';
        name = "開門方向";
        break;
    }

    // Calculation for rotation (Line/Wall needs it)
    let rotation = 0;
    if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_ARC) {
       rotation = -Math.atan2(dz, dx); // Three.js rotation is counter-clockwise, atan2 is standard math
       // Adjustment for Three.js coordinates
       // If I draw along X, angle is 0.
       // If I draw along Z, angle is 90 (PI/2).
       // atan2(z, x) gives math angle.
       // In 3D: Rot Y.
       rotation = -Math.atan2(dz, dx); 
    }

    const newShape: IShape = {
      id: `shape-${Date.now()}`,
      name: `${name} ${Date.now().toString().slice(-4)}`,
      type: shapeType,
      points,
      height: shapeType === 'solid' ? DEFAULT_HEIGHT : 0.01,
      color: shapeType === 'flat' ? '#fbbf24' : DEFAULT_COLOR, // Flat shapes default to yellow (warning/info)
      position: pos,
      rotation: rotation
    };

    addShape(newShape);
    setStartPoint(null);
  };

  const finishShape = (pts: IPoint[]) => {
    // For polygon
    if (pts.length < 3) return;
    // Calc center to normalize points
    // Simple average
    const cx = pts.reduce((sum, p) => sum + p.x, 0) / pts.length;
    const cz = pts.reduce((sum, p) => sum + p.z, 0) / pts.length;

    // Offset points
    const centeredPoints = pts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
    // Add start to close if not closed
    centeredPoints.push(centeredPoints[0]);

    const newShape: IShape = {
      id: `poly-${Date.now()}`,
      name: `多邊形`,
      type: 'solid',
      points: centeredPoints,
      height: DEFAULT_HEIGHT,
      color: DEFAULT_COLOR,
      position: [cx, 0, cz],
      rotation: 0
    };
    addShape(newShape);
    setPolyPoints([]);
    setStartPoint(null);
  };

  // Render Visual Guides
  return (
    <>
      <mesh 
        rotation={[-Math.PI / 2, 0, 0]} 
        position={[0, 0.01, 0]} 
        onPointerMove={handlePointerMove}
        onClick={handleClick}
        visible={false}
      >
        <planeGeometry args={[100, 100]} />
      </mesh>

      {/* Cursor Indicator */}
      {currentPoint && tool !== ToolType.SELECT && (
        <mesh position={[currentPoint.x, 0.05, currentPoint.z]} rotation={[-Math.PI / 2, 0, 0]}>
          <ringGeometry args={[0.1, 0.15, 32]} />
          <meshBasicMaterial color="red" />
        </mesh>
      )}

      {/* Dynamic Dimensions Tooltip */}
      {currentPoint && startPoint && (
        <CursorTooltip 
           position={new THREE.Vector3(
             (startPoint.x + currentPoint.x)/2, 
             0, 
             (startPoint.z + currentPoint.z)/2
           )}
           text={(() => {
             const dx = Math.abs(currentPoint.x - startPoint.x);
             const dz = Math.abs(currentPoint.z - startPoint.z);
             const dist = Math.sqrt(Math.pow(currentPoint.x - startPoint.x, 2) + Math.pow(currentPoint.z - startPoint.z, 2));

             if (tool === ToolType.DRAW_RECT) return `${formatValue(dx)} x ${formatValue(dz)}`;
             if (tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) return `R: ${formatValue(dist)}`;
             return `L: ${formatValue(dist)}`;
           })()}
        />
      )}

      {/* Drawing Preview Lines */}
      {tool === ToolType.DRAW_POLY && polyPoints.length > 0 && (
         <line>
           <bufferGeometry>
             <bufferAttribute
               attach="attributes-position"
               count={polyPoints.length + (currentPoint ? 1 : 0)}
               array={new Float32Array([
                 ...polyPoints.flatMap(p => [p.x, 0.1, p.z]),
                 ...(currentPoint ? [currentPoint.x, 0.1, currentPoint.z] : [])
               ])}
               itemSize={3}
             />
           </bufferGeometry>
           <lineBasicMaterial color="red" linewidth={2} />
         </line>
      )}

      {/* 2-Step Preview (Ghost Shape) */}
      {startPoint && currentPoint && tool !== ToolType.DRAW_POLY && (
        <line>
          <bufferGeometry>
            <bufferAttribute
              attach="attributes-position"
              count={2}
              array={new Float32Array([startPoint.x, 0.1, startPoint.z, currentPoint.x, 0.1, currentPoint.z])}
              itemSize={3}
            />
          </bufferGeometry>
          <lineBasicMaterial color="red" linewidth={2} dashSize={0.2} gapSize={0.1} />
        </line>
      )}
    </>
  );
};

// Individual Extruded Shape
const RenderedShape: React.FC<{ shape: IShape }> = ({ shape }) => {
  const { selectedId, setSelectedId, tool, updateShape } = useApp();
  const isSelected = selectedId === shape.id;

  const threeShape = useMemo(() => createThreeShape(shape.points), [shape.points]);

  // If flat (like arc), do not extrude, just use ShapeGeometry
  // If solid, use ExtrudeGeometry
  const geometry = useMemo(() => {
    if (shape.type === 'flat') {
      return new THREE.ShapeGeometry(threeShape);
    }
    return new THREE.ExtrudeGeometry(threeShape, { depth: shape.height, bevelEnabled: false });
  }, [threeShape, shape.height, shape.type]);

  const handleClick = (e: ThreeEvent<MouseEvent>) => {
    if (tool === ToolType.SELECT) {
      e.stopPropagation();
      setSelectedId(shape.id);
    }
  };

  return (
    <group>
      <mesh 
        position={shape.position} 
        rotation={[-Math.PI / 2, 0, shape.rotation]} // Rotate -90 on X to lay flat, then shape rotation
        onClick={handleClick}
      >
        <primitive object={geometry} attach="geometry" />
        <meshStandardMaterial 
          color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
          transparent={isSelected || shape.type === 'flat'} 
          opacity={shape.type === 'flat' ? 0.6 : (isSelected ? 0.8 : 1)}
          side={THREE.DoubleSide}
        />
        {isSelected && (
           <lineSegments>
             <edgesGeometry args={[geometry]} />
             <lineBasicMaterial color="white" />
           </lineSegments>
        )}
      </mesh>

      {/* Transform Controls for Moving/Rotating */}
      {isSelected && tool === ToolType.SELECT && (
        <TransformControls 
          position={shape.position} 
          rotation={[0, shape.rotation, 0]}
          mode="translate" // Default mode, we can add a toggle later if needed, but properties panel handles rotation well
          onObjectChange={(e: any) => {
            // Update shape position in state when dragged
            if (e?.target?.object) {
               const pos = e.target.object.position;
               // e.target.object is the helper target, we need to map back.
               // Actually TransformControls modifies the object it attaches to.
               // However, we are rendering the mesh inside.
               // Let's use the callback to update the store.
               // Note: TransformControls attaches to the child mesh if we wrap it?
               // The correct way in R3F with controlled state is slightly complex.
               // Easier way: Use TransformControls as a wrapper or alongside.
            }
          }}
          onMouseUp={(e: any) => {
             // Commit the change
             // We need to read the new position from the *control's target*?
             // Or simpler: The TransformControls modifies the mutable ref of the object.
             // We need a ref to the mesh.
          }}
        />
      )}
    </group>
  );
};

// Wrapper for RenderedShape to handle TransformControls properly
const ShapeWrapper: React.FC<{ shape: IShape }> = ({ shape }) => {
  const { selectedId, updateShape, tool } = useApp();
  const isSelected = selectedId === shape.id;
  const meshRef = useRef<THREE.Mesh>(null);

  const handleTransformEnd = () => {
    if (meshRef.current) {
      const p = meshRef.current.position;
      const r = meshRef.current.rotation;
      // Note: Our local rotation logic is slightly different (mesh is rotated -90 X).
      // The group is positioned. 
      // Let's attach TransformControls to a Group to keep it clean.
      updateShape(shape.id, {
        position: [p.x, p.y, p.z],
        // rotation: r.y // Rotation via gizmo might be tricky due to axis order, let's stick to translation for Gizmo
      });
    }
  };

  return (
    <>
      <TransformControls 
        object={meshRef} 
        mode="translate"
        enabled={isSelected && tool === ToolType.SELECT}
        showX={isSelected && tool === ToolType.SELECT}
        showY={false} // Disable vertical movement (keep on floor)
        showZ={isSelected && tool === ToolType.SELECT}
        onMouseUp={handleTransformEnd}
      >
        <group position={shape.position} rotation={[0, shape.rotation, 0]} ref={meshRef as any}>
            <RenderedShape shape={shape} />
        </group>
      </TransformControls>
    </>
  )
}

// Internal Shape Renderer (Pure)
const InnerShape: React.FC<{ shape: IShape, onClick: (e: ThreeEvent<MouseEvent>) => void, isSelected: boolean }> = ({ shape, onClick, isSelected }) => {
  const threeShape = useMemo(() => createThreeShape(shape.points), [shape.points]);

  const geometry = useMemo(() => {
    if (shape.type === 'flat') {
      return new THREE.ShapeGeometry(threeShape);
    }
    return new THREE.ExtrudeGeometry(threeShape, { depth: shape.height, bevelEnabled: false });
  }, [threeShape, shape.height, shape.type]);

  return (
    <mesh 
      rotation={[-Math.PI / 2, 0, 0]} 
      onClick={onClick}
    >
      <primitive object={geometry} attach="geometry" />
      <meshStandardMaterial 
        color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
        transparent={isSelected || shape.type === 'flat'} 
        opacity={shape.type === 'flat' ? 0.6 : (isSelected ? 0.8 : 1)}
        side={THREE.DoubleSide}
      />
      {isSelected && (
          <lineSegments>
            <edgesGeometry args={[geometry]} />
            <lineBasicMaterial color="white" />
          </lineSegments>
      )}
    </mesh>
  );
}

const SceneContent: React.FC = () => {
  const { shapes, tool, setSelectedId, updateShape, selectedId } = useApp();

  return (
    <>
      <ambientLight intensity={0.7} />
      <directionalLight position={[10, 20, 10]} intensity={1} castShadow />
      <Environment preset="city" />

      <Grid 
        infiniteGrid 
        cellSize={1} 
        sectionSize={5} 
        fadeDistance={50} 
        sectionColor="#64748b" 
        cellColor="#475569" 
      />

      <DrawingManager />

      {shapes.map(shape => {
         const isSelected = selectedId === shape.id;

         return (
           <group key={shape.id}>
             {isSelected && tool === ToolType.SELECT ? (
                <TransformControls
                  position={shape.position}
                  rotation={[0, shape.rotation, 0]}
                  mode="translate"
                  showY={false} // Lock to floor
                  onMouseUp={(e: any) => {
                    // We need to read the object's world position or local position relative to scene
                    // The object inside TransformControls is the one being mutated.
                    if (e?.target?.object) {
                       const p = e.target.object.position;
                       // Important: e.target.object is the Group we passed as children
                       updateShape(shape.id, { position: [p.x, p.y, p.z] });
                    }
                  }}
                >
                  <group>
                     <InnerShape 
                        shape={shape} 
                        isSelected={true} 
                        onClick={(e) => { e.stopPropagation(); setSelectedId(shape.id); }} 
                     />
                  </group>
                </TransformControls>
             ) : (
                <group position={shape.position} rotation={[0, shape.rotation, 0]}>
                   <InnerShape 
                      shape={shape} 
                      isSelected={false} 
                      onClick={(e) => { 
                        if (tool === ToolType.SELECT) {
                          e.stopPropagation(); 
                          setSelectedId(shape.id); 
                        }
                      }} 
                   />
                </group>
             )}
           </group>
         );
      })}

      <OrbitControls 
        makeDefault 
        enabled={tool === ToolType.SELECT} // Only orbit in select mode
        maxPolarAngle={Math.PI / 2 - 0.1} 
      />
    </>
  );
};

